-- The FIMI X8 app's route database schema (com.fimi.app.x8m, V1.1.43.20703),
-- empty. app.py creates fimi.db from this when no database exists yet;
-- read.py pulls a real one from the phone.
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE IF NOT EXISTS "DATA_STATIC_INFO" ("_id" INTEGER PRIMARY KEY ,"CURRENT_TIME" TEXT,"FLY_TIME" TEXT,"USER_ID" TEXT,"USE_TIME" TEXT,"TYPE" INTEGER NOT NULL ,"DEVICE_TYPE" INTEGER NOT NULL ,"SYS_VERSION" TEXT,"MCU_VERSION" TEXT,"FLY_DISTANCE" TEXT,"FLY_HEIGHT" TEXT,"LONGITUDE" TEXT,"LATITUDE" TEXT);
CREATE TABLE IF NOT EXISTS "DYNAMIC_NFZ" ("_id" INTEGER PRIMARY KEY AUTOINCREMENT ,"DEVICE_TYPE" TEXT,"ENCRYPT_VALUE" TEXT,"START_DATE" INTEGER NOT NULL ,"END_DATE" INTEGER NOT NULL ,"INSERT_DATE" INTEGER NOT NULL ,"LATITUDE" REAL NOT NULL ,"LOGITUDE" REAL NOT NULL ,"NO_FLY_TYPE" TEXT,"LIMIT_HEIGHT" INTEGER NOT NULL ,"FORBIDDEN_RADIUS" INTEGER NOT NULL ,"LIMIT_RADIUS" INTEGER NOT NULL ,"WARIN_RADIUS" INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS "GH2_DATA_STATIC_INFO" ("_id" INTEGER PRIMARY KEY ,"PRODUCT_MODEL" TEXT,"HANDLE_VERSION" INTEGER NOT NULL ,"GIMBAL_VERSION" INTEGER NOT NULL ,"USE_TIME" REAL NOT NULL ,"LONGITUDE" REAL NOT NULL ,"LATITUDE" REAL NOT NULL ,"CREATE_TIME" TEXT);
CREATE TABLE IF NOT EXISTS "MEDIA_DOWNLOAD_INFO" ("_id" INTEGER PRIMARY KEY ,"START_POS" INTEGER NOT NULL ,"END_POS" INTEGER NOT NULL ,"COMPELETE_ZIZE" INTEGER NOT NULL ,"URL" TEXT);
CREATE TABLE IF NOT EXISTS "STUDENT" ("_id" INTEGER PRIMARY KEY ,"NAME" TEXT,"AGE" TEXT,"NUMBER" TEXT);
CREATE TABLE IF NOT EXISTS "X8_AI_LINE_POINT_INFO" ("_id" INTEGER PRIMARY KEY ,"TIME" INTEGER NOT NULL ,"NAME" TEXT,"TYPE" INTEGER NOT NULL ,"SPEED" INTEGER NOT NULL ,"SAVE_FLAG" INTEGER NOT NULL ,"DISTANCE" REAL NOT NULL ,"IS_CURVE" INTEGER NOT NULL ,"MAP_TYPE" INTEGER NOT NULL ,"RUN_BY_MAP_OR_VEDIO" INTEGER NOT NULL ,"DISCONNECT_TYPE" INTEGER NOT NULL ,"EXCUTE_END" INTEGER NOT NULL ,"AUTO_RECORD" INTEGER NOT NULL ,"LOCALITY" TEXT,"ESTIMATED_TIME" TEXT);
CREATE TABLE IF NOT EXISTS "X8_AI_LINE_POINT_LATLNG_INFO" ("_id" INTEGER PRIMARY KEY ,"NUMBER" INTEGER NOT NULL ,"TOTALNUMBER" INTEGER NOT NULL ,"LONGITUDE" REAL NOT NULL ,"LATITUDE" REAL NOT NULL ,"ALTITUDE" INTEGER NOT NULL ,"YAW" REAL NOT NULL ,"GIMBAL_PITCH" INTEGER NOT NULL ,"SPEED" INTEGER NOT NULL ,"YAW_MODE" INTEGER NOT NULL ,"GIMBAL_MODE" INTEGER NOT NULL ,"TRAJECTORY_MODE" INTEGER NOT NULL ,"MISSION_FINISH_ACTION" INTEGER NOT NULL ,"R_CLOST_ACTION" INTEGER NOT NULL ,"LONGITUDE_POI" REAL NOT NULL ,"LATITUDE_POI" REAL NOT NULL ,"ALTITUDE_POI" INTEGER NOT NULL ,"LINE_ID" INTEGER NOT NULL ,"POINT_ACTION_CMD" INTEGER NOT NULL ,"RORATION" INTEGER NOT NULL );
INSERT INTO android_metadata VALUES ('en_US');
